    name: { de: "Finanzdistrikt Kirchberg", hu: "Kirchberg pénzügyi negyed", ro: "Districtul financiar Kirchberg", en: "Kirchberg Financial District"},
    image: "/poi-images/luxembourg-kirchberg-district-economic-v2.webp",
