      es: ["Fundación de la fábrica en el año 1951", "Sitio de Goodyear más grande fuera de EE. UU.", "Alberga el centro de innovación con 1.000 expertos", "Especializado en neumáticos para camiones y máquinas de construcción", "Pista de pruebas propia para ensayos de productos en el sitio", "Uno de los mayores empleadores privados en Luxemburgo"],
      pt: ["Fundação da fábrica no ano de 1951", "Maior unidade da Goodyear fora dos EUA", "Abriga o Centro de Inovação com 1.000 especialistas", "Especializada em pneus para camiões e máquinas de terraplenagem", "Pista de testes própria para verificação de produtos no local", "Um dos maiores empregadores privados no Luxemburgo"],
      fr: ["Fondation de l'usine en 1951", "Plus grand site Goodyear hors des États-Unis", "Abrite le centre d'innovation avec 1 000 experts", "Spécialisé dans les pneus pour camions et engins de génie civil", "Propre piste d'essai pour les tests de produits sur place", "L'un des plus grands employeurs privés du Luxembourg"],
