      pt: ["Raízes da empresa na década de 1930", "Inauguração do complexo RTL City em 2017", "Parte do grupo internacional Bertelsmann", "Opera mais de 60 canais de televisão e 30 de rádio", "Sede da RTL Télé Lëtzebuerg no edifício", "Localização estratégica no bairro de negócios de Kirchberg"],
      fr: ["Racines de l'entreprise dans les années 1930", "Inauguration du complexe RTL City en 2017", "Fait partie du groupe international Bertelsmann", "Exploite plus de 60 chaînes de télévision et 30 stations de radio", "Siège de RTL Télé Lëtzebuerg dans le bâtiment", "Emplacement stratégique dans le quartier d'affaires du Kirchberg"],
