      hu: "A dudelange-i gyár a síkacél nemesítésére szakosodott. Itt kiváló minőségű bevont lemezeket gyártanak, amelyeket elsősorban az autóiparban használnak karosszériaelemekhez.",
      ro: "Fabrica din Dudelange este specializată în finisarea oțelului plat. Aici sunt produse table acoperite de înaltă calitate, utilizate în principal în industria auto pentru piese de caroserie.",
