      es: ["Fundación de la fundición en el año 1882.", "Especialización en chapas de acero con recubrimiento Alusi.", "Importante proveedor para el sector automotriz.", "Cuenta con modernas instalaciones de galvanizado en caliente.", "Parte de la red global de ArcelorMittal.", "Motor histórico para el desarrollo urbano de Dudelange."],
      pt: ["Fundação da fundição no ano de 1882.", "Especialização em chapas de aço com revestimento Alusi.", "Fornecedor importante para o setor automóvel.", "Dispõe de modernas instalações de galvanização a quente.", "Parte da rede global da ArcelorMittal.", "Motor histórico para o desenvolvimento urbano de Dudelange."],
      fr: ["Fondation de l'usine sidérurgique en 1882.", "Spécialisation dans les tôles d'acier à revêtement Alusi.", "Fournisseur majeur pour le secteur automobile.", "Dispose d'installations de galvanisation à chaud modernes.", "Fait partie du réseau mondial ArcelorMittal.", "Moteur historique du développement urbain de Dudelange."],
