      es: ["Fundación de la cooperativa en el año 1894", "Traslado a la moderna ubicación de Roost en 2009", "Propiedad de unos 350 productores de leche locales", "Produce el tradicional queso Kachkéis", "Alberga el centro de visitantes interactivo Vitarium", "Procesamiento de más de 160 millones de litros de leche al año"],
