      es: ["Ubicación de la trefilería de ArcelorMittal", "Centro de logística y tecnología de datos", "Situado estratégicamente junto a la A7", "Enfoque en infraestructura digital"],
      pt: ["Local da trefilagem da ArcelorMittal", "Centro de logística e tecnologia de dados", "Estrategicamente localizado junto à A7", "Foco na infraestrutura digital"],
