      hu: ["A tervezett Google adatközpont helyszíne", "Az IEE vállalat székhelyének otthona", "Stratégiai elhelyezkedés az A7 autópálya mentén", "Fókuszban a csúcstechnológia és a digitális gazdaság", "Több hektáros terület ipari betelepülésre", "Bissen község része Luxemburg szívében"],
