      es: ["Sitio del proyectado centro de datos de Google", "Alberga la sede de la empresa IEE", "Ubicación estratégica en la autopista A7", "Enfoque en alta tecnología y economía digital", "Superficie de varias hectáreas para asentamientos industriales", "Parte del municipio de Bissen, en el centro de Luxemburgo"],
      pt: ["Local do planeado centro de dados da Google", "Abriga a sede da empresa IEE", "Localização estratégica na autoestrada A7", "Foco em alta tecnologia e economia digital", "Área de vários hectares para instalação industrial", "Parte do município de Bissen, no centro do Luxemburgo"],
      fr: ["Site du futur centre de données de Google", "Abrite le siège de la société IEE", "Emplacement stratégique sur l'autoroute A7", "Focus sur la haute technologie et l'économie numérique", "Surface de plusieurs hectares pour l'implantation industrielle", "Fait partie de la commune de Bissen au centre du Luxembourg"],
