      pt: ["Local da empresa química DuPont de Nemours", "Hub importante para empresas de logística como a Kuehne + Nagel", "Abriga a empresa tradicional Chaux de Contern", "Excelente ligação ao aeroporto Findel", "Dispõe de uma rede própria de linhas industriais", "Centro para a indústria de construção e fabricação"],
      fr: ["Site de l'entreprise chimique DuPont de Nemours", "Hub majeur pour les sociétés de logistique comme Kuehne + Nagel", "Abrite l'entreprise traditionnelle Chaux de Contern", "Excellente connexion à l'aéroport du Findel", "Dispose de son propre réseau de voies ferrées industrielles", "Centre pour l'industrie du bâtiment et de la fabrication"],
