      pt: ["Único porto fluvial do Grão-Ducado do Luxemburgo", "Inauguração oficial no ano 1966", "Ponto central de transbordo de produtos petrolíferos", "Situado no Mosela canalizado", "Ligação multimodal por caminho-de-ferro e estrada", "A área total do complexo portuário é de 65 hectares"],
      fr: ["Seul port fluvial du Grand-Duché de Luxembourg", "Inauguration officielle en 1966", "Plaque tournante centrale pour les produits pétroliers", "Situé sur la Moselle canalisée", "Connexion multimodale au rail et à la route", "La surface totale de l'installation portuaire est de 65 hectares"],
