      hu: ["PET-előformákra szakosodott", "Globális szervizközpont Luxemburgban", "Magasan automatizált gyártási folyamatok", "A luxemburgi gépgyártás fontos szereplője"],
      ro: ["Specializare în preforme PET", "Centru global de service în Luxemburg", "Procese de fabricație înalt automatizate", "Actor important în construcția de mașini din Luxemburg"],
      en: ["Specialization in PET preforms", "Global service center in Luxembourg", "Highly automated manufacturing processes", "Key player in Luxembourgish mechanical engineering"],
      es: ["Especialización en preformas de PET", "Centro de servicio global en Luxemburgo", "Procesos de fabricación altamente automatizados", "Actor importante en la ingeniería mecánica luxemburguesa"],
