      en: ["Founded in 1985 in Echternach", "Specializes in honeycomb lightweight structures", "Key supplier for Airbus and Boeing", "Employs approximately 850 people at the site", "Materials are used in space exploration (satellites)", "Certified partner of the global aviation industry"],
