imageHint: "Modern office and lab building of IEE in Contern",
    descriptionAdvanced: {
      de: "IEE (Interactive Evolutionary Economy) ist ein weltweit führender Innovator im Bereich der intelligenten Sensorik, mit Hauptsitz in Contern. Das 1989 gegründete Unternehmen hat sich auf die Entwicklung und Produktion von Sensorsystemen spezialisiert, die primär in der Automobilindustrie eingesetzt werden. Bekannt wurde IEE durch die Einführung der Sitzbelegungserkennung, die heute zur Standardausrüstung für die Steuerung von Airbags in modernen Fahrzeugen gehört. Das Portfolio umfasst zudem Lösungen zur Kindersitzerkennung, Fußgängerschutz und Innenraumüberwachung. Seit 2019 ist das Unternehmen in seinem neuen, hochmodernen Hauptsitz in Contern ansässig, der Forschung, Entwicklung und Verwaltung unter einem Dach vereint. IEE investiert massiv in neue Technologien wie 3D-Bildsensorik und Wearables für die Gesundheitsbranche. Als global agierendes Unternehmen betreibt IEE Produktionsstätten und Vertriebsbüros in Europa, Asien und den USA. Die Verlegung des Hauptsitzes nach Contern unterstreicht das Bekenntnis des Unternehmens zum Standort Luxemburg als Zentrum für Hochtechnologie und Innovation.",
      hu: "Az IEE (Interactive Evolutionary Economy) az intelligens szenzortechnológia egyik világvezető innovátora, amelynek központja Conternben található. Az 1989-ben alapított vállalat olyan érzékelőrendszerek fejlesztésére és gyártására specializálódott, amelyeket elsősorban az autóiparban alkalmaznak. Az IEE az ülésfoglaltság-érzékelő bevezetésével vált ismertté, amely ma már alapfelszereltség a modern járművek légzsákvezérlésénél. A portfóliójuk tartalmaz gyermekülés-felismerő, gyalogosvédelmi és utastér-felügyeleti megoldásokat is. 2019 óta a vállalat új, ultramodern conterni központjában székel, amely egy fedél alatt egyesíti a kutatást, a fejlesztést és az adminisztrációt. Az IEE jelentős összegeket fektet be olyan új technológiákba, mint a 3D képérzékelés és az egészségügyi célú hordható eszközök. Globális szereplőként a cég Európában, Ázsiában és az USA-ban is működtet gyárakat és értékesítési irodákat. A központ Conternbe költöztetése megerősíti a vállalat elkötelezettségét Luxemburg, mint a csúcstechnológia és az innováció központja mellett.",
      ro: "IEE (Interactive Evolutionary Economy) este un inovator de talie mondială în domeniul tehnologiei senzorilor inteligenți, având sediul central în Contern. Fondată în 1989, compania s-a specializat în dezvoltarea și producția de sisteme de senzori utilizate cu precădere în industria auto. IEE a devenit celebră prin introducerea senzorului de detectare a prezenței pasagerilor, care a devenit astăzi un standard pentru controlul airbag-urilor în vehiculele moderne. Portofoliul lor include, de asemenea, soluții pentru detectarea scaunelor de copii, protecția pietonilor și monitorizarea habitaclului. Din 2019, compania își desfășoară activitatea în noul său sediu ultra-modern din Contern, care reunește sub același acoperiș cercetarea, dezvoltarea și administrația. IEE investește masiv în tehnologii noi, cum ar fi senzorii de imagine 3D și dispozitivele purtabile (wearables) pentru sectorul sănătății. Ca jucător global, IEE operează unități de producție și birouri de vânzări în Europa, Asia și SUA. Relocarea sediului la Contern subliniază angajamentul companiei față de Luxemburg ca centru de înaltă tehnologie și inovație.",
      en: "IEE (Interactive Evolutionary Economy) is a world-leading innovator in intelligent sensing solutions, headquartered in Contern. Founded in 1989, the company specializes in developing and manufacturing sensor systems primarily for the automotive industry. IEE gained global recognition for introducing Seat Occupancy Detection, which is now standard equipment for controlling airbags in modern vehicles. Its portfolio also includes child seat detection, pedestrian protection, and cabin monitoring solutions. Since 2019, the company has been based in its new, state-of-the-art headquarters in Contern, which integrates research, development, and administration under one roof. IEE invests heavily in emerging technologies such as 3D image sensing and wearables for the healthcare industry. As a global player, IEE operates manufacturing plants and sales offices across Europe, Asia, and the USA. The relocation of its headquarters to Contern reinforces the company's commitment to Luxembourg as a hub for high-tech industry and innovation.",
      es: "IEE en Contern es un pionero en tecnología de sensores cuyos sistemas garantizan la seguridad y el confort en millones de vehículos en todo el mundo.",
      pt: "A IEE em Contern é pioneira na tecnologia de sensores, cujos sistemas garantem segurança e conforto em milhões de veículos em todo o mundo.",
      fr: "IEE à Contern est un pionnier de la technologie des capteurs, dont les systèmes assurent sécurité et confort dans des millions de véhicules à travers le monde.",
    },
